 a=MANUAL_LABELS.get(r['record_key'])
 if a:r.update(a)
 else:r.update(experience_status='unknown',paraphrase_code='not_yet_source_inspected_by_ai',source_inspected_by_ai=False,excluded_promotional_content=False,independently_verified=False)
